def _fraction_str(value: float, max_denominator: int = 12) -> str:
    """Convert a float to a string representation of a fraction with a limited denominator.
    If the denominator is 1, return the integer as a string.
    """
    frac = Fraction(value).limit_denominator(max_denominator)
    if frac.denominator == 1:
        return str(frac.numerator)
    return f"{frac.numerator}/{frac.denominator}"


def analyze_wyckoff_position_multiplicities_and_coordinates(filepath: str) -> Tuple[Dict[str, Dict[str, Any]], Dict[str, Any]]:
    """Analyze Wyckoff multiplicities and approximate coordinates for the first atom of each Wyckoff position.

    Parameters
    ----------
    filepath : str
        Path to a CIF file.

    Returns
    -------
    dict
        A dictionary with two keys:
        - "wyckoff_multiplicity_dict": mapping Wyckoff letters to their multiplicities.
        - "wyckoff_coordinates_dict": mapping Wyckoff letters to a list of three fractional coordinate strings.
    """
    if not os.path.isfile(filepath):
        return {"error": f"File not found: {filepath}"}
    if Structure is None or SpacegroupAnalyzer is None:
        return {"error": "pymatgen is not available in the environment."}
    try:
        # Load the structure from the CIF file
        struct = Structure.from_file(filepath)
        # Obtain the symmetrized structure which contains Wyckoff information
        sga = SpacegroupAnalyzer(struct)
        sym_struct = sga.get_symmetrized_structure()
        # sym_struct.equivalent_sites is a list of lists of Site objects sharing the same Wyckoff letter
        # sym_struct.wyckoff_symbols gives the Wyckoff letter for each site in the original structure order.
        # Build a mapping from Wyckoff letter to its group of sites (first occurrence defines the group)
        wyckoff_to_sites: Dict[str, list] = {}
        for group in sym_struct.equivalent_sites:
            # All sites in a group share the same Wyckoff letter; take the first site's label
            wyckoff_letter = sym_struct.wyckoff_symbols[sym_struct.sites.index(group[0])]
            wyckoff_to_sites[wyckoff_letter] = group
        # Prepare output dictionaries
        wyckoff_multiplicity_dict: Dict[str, int] = {}
        wyckoff_coordinates_dict: Dict[str, list] = {}
        for letter, sites in wyckoff_to_sites.items():
            wyckoff_multiplicity_dict[letter] = len(sites)
            # Take the first site in the group for coordinate approximation
            frac_coords = sites[0].frac_coords
            coord_strings = [_fraction_str(coord) for coord in frac_coords]
            wyckoff_coordinates_dict[letter] = coord_strings
        return {
            "wyckoff_multiplicity_dict": wyckoff_multiplicity_dict,
            "wyckoff_coordinates_dict": wyckoff_coordinates_dict,
        }
    except Exception as exc:
        return {"error": str(exc)}
